css:
.rsd-earnings-model{--rsd1-ln:#1E2634;--rsd1-tx:#E8EDF7;--rsd1-dm:#78859B;--rsd1-up:#35D0A5;--rsd1-dn:#FF5D6B;--rsd1-mn:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;box-sizing:border-box;width:100%;max-width:352px;padding:10px 11px 9px;border:1px solid var(--rsd1-ln);border-radius:12px;background:linear-gradient(180deg,#121826,#0B0F17);color:var(--rsd1-tx);font:500 11px/1.25 system-ui,-apple-system,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;font-variant-numeric:tabular-nums}
.rsd-earnings-model *{box-sizing:border-box}
.rsd-earnings-model__hd{display:flex;align-items:center;justify-content:space-between;gap:8px;margin-bottom:8px}
.rsd-earnings-model__id{display:flex;flex-direction:column;gap:3px;min-width:0}
.rsd-earnings-model__id b{font:700 12.5px/1 var(--rsd1-mn);letter-spacing:.02em}
.rsd-earnings-model__id span{font-size:8.5px;color:var(--rsd1-dm);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.rsd-earnings-model__seg{display:flex;flex:none;border:1px solid var(--rsd1-ln);border-radius:6px;overflow:hidden;background:#0E1420}
.rsd-earnings-model__tab{appearance:none;border:0;background:transparent;color:var(--rsd1-dm);font:700 8.5px/1 var(--rsd1-mn);letter-spacing:.06em;padding:6px 7px;cursor:pointer}
.rsd-earnings-model__tab+.rsd-earnings-model__tab{border-left:1px solid var(--rsd1-ln)}
.rsd-earnings-model__tab[aria-pressed="true"]{background:#1B2436;color:#CFE0FF}
.rsd-earnings-model__cols,.rsd-earnings-model__r{display:grid;grid-template-columns:1fr 60px 52px 54px;column-gap:6px;align-items:baseline}
.rsd-earnings-model__cols{font:600 7.5px/1 var(--rsd1-mn);letter-spacing:.09em;color:#55607A;padding-bottom:5px;border-bottom:1px solid var(--rsd1-ln)}
.rsd-earnings-model__cols span+span{text-align:right}
.rsd-earnings-model__r{padding:5px 0 4px;border-bottom:1px solid rgba(30,38,52,.55)}
.rsd-earnings-model__m{font-size:10px;color:#B9C4D6;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.rsd-earnings-model__m i{font-style:normal;font:600 7.5px/1 var(--rsd1-mn);color:#4E5A70;margin-left:4px}
.rsd-earnings-model__a{font:700 11.5px/1 var(--rsd1-mn);text-align:right}
.rsd-earnings-model__c{font:500 10px/1 var(--rsd1-mn);text-align:right;color:#8A96AC}
.rsd-earnings-model__d{font:700 10px/1 var(--rsd1-mn);text-align:right}
.rsd-earnings-model__r[data-s="up"] .rsd-earnings-model__d{color:var(--rsd1-up)}
.rsd-earnings-model__r[data-s="dn"] .rsd-earnings-model__d{color:var(--rsd1-dn)}
.rsd-earnings-model__bar{grid-column:1/5;position:relative;height:3px;margin-top:5px;border-radius:2px;background:#141B29;overflow:hidden}
.rsd-earnings-model__mid{position:absolute;left:50%;top:0;bottom:0;width:1px;background:#2C374B;z-index:2}
.rsd-earnings-model__fill{position:absolute;top:0;bottom:0;left:50%;width:0;background:var(--rsd1-up);transition:width .55s cubic-bezier(.3,.9,.3,1),left .55s cubic-bezier(.3,.9,.3,1)}
.rsd-earnings-model__r[data-s="dn"] .rsd-earnings-model__fill{background:var(--rsd1-dn)}
.rsd-earnings-model__ft{display:flex;align-items:center;gap:7px;margin-top:8px}
.rsd-earnings-model__beat{flex:none;font:700 8.5px/1 var(--rsd1-mn);letter-spacing:.05em;color:#06210E;background:var(--rsd1-up);border-radius:3px;padding:4px 5px}
