var M=[
 {n:'Revenue',u:'$m',a:1482.6,c:1451.0,p:1298.3,d:1},
 {n:'EBITDA',u:'$m',a:421.5,c:402.8,p:344.9,d:1},
 {n:'EBITDA margin',u:'%',a:0,c:0,p:0,d:1,mg:1},
 {n:'EPS adj',u:'$',a:1.34,c:1.27,p:1.06,d:2},
 {n:'Free cash flow',u:'$m',a:268.4,c:241.0,p:205.2,d:1}
];
M[2].a=M[1].a/M[0].a*100;M[2].c=M[1].c/M[0].c*100;M[2].p=M[1].p/M[0].p*100;
var wrap=root.querySelector('.rsd-earnings-model__rows');
var cHd=root.querySelector('.rsd-earnings-model__ch');
var beat=root.querySelector('.rsd-earnings-model__beat');
var note=root.querySelector('.rsd-earnings-model__note');
var tabs=root.querySelectorAll('.rsd-earnings-model__tab');
function f(v,d){var s=Math.abs(v).toFixed(d).split('.');s[0]=s[0].replace(/\B(?=(\d{3})+(?!\d))/g,',');return (v<0?'-':'')+s.join('.');}
function sg(v,d){return (v>=0?'+':'-')+Math.abs(v).toFixed(d);}
var rows=M.map(function(m){
  var r=document.createElement('div');r.className='rsd-earnings-model__r';
  r.innerHTML='<span class="rsd-earnings-model__m"></span><span class="rsd-earnings-model__a"></span>'+
    '<span class="rsd-earnings-model__c"></span><span class="rsd-earnings-model__d"></span>'+
    '<span class="rsd-earnings-model__bar"><i class="rsd-earnings-model__fill"></i><i class="rsd-earnings-model__mid"></i></span>';
  r.querySelector('.rsd-earnings-model__m').innerHTML=m.n+'<i>'+m.u+'</i>';
  r.querySelector('.rsd-earnings-model__a').textContent=f(m.a,m.d);
  wrap.appendChild(r);return r;});
function draw(mode){
  var mag=M.map(function(m){var b=mode==='cons'?m.c:m.p;return m.mg?(m.a-b):(m.a/b-1)*100;});
  var mx=Math.max.apply(null,mag.map(Math.abs))*1.12;
  M.forEach(function(m,i){
    var b=mode==='cons'?m.c:m.p,r=rows[i],v=mag[i];
    r.setAttribute('data-s',v>=0?'up':'dn');
    r.querySelector('.rsd-earnings-model__c').textContent=f(b,m.d);
    r.querySelector('.rsd-earnings-model__d').textContent=m.mg?sg(v*100,0)+'bp':sg(v,1)+'%';
    var w=Math.min(49,Math.abs(v)/mx*49),fl=r.querySelector('.rsd-earnings-model__fill');
    fl.style.width=w+'%';fl.style.left=(v>=0?50:50-w)+'%';
  });
  cHd.textContent=mode==='cons'?'CONS':'Q3 FY24';
  beat.textContent=mag.filter(function(v){return v>0;}).length+' / '+mag.length+(mode==='cons'?' BEAT':' UP YoY');
  note.textContent=mode==='cons'?'FY25 guide raised to 5,880–5,940 (cons 5,842)':'Base: Q3 FY24 reported 30 Aug 2024 · cc growth +12.8%';
}
Array.prototype.forEach.call(tabs,function(t){
  t.addEventListener('click',function(){
    Array.prototype.forEach.call(tabs,function(o){o.setAttribute('aria-pressed',String(o===t));});
    draw(t.getAttribute('data-mode'));});});
draw('cons');

