  var k=body.children;
  for(var i=0;i<k.length;i++){if(i===sel)k[i].setAttribute('data-sel','1');else k[i].removeAttribute('data-sel');}
  if(view[sel])pick.textContent='▸ '+view[sel].t+' · '+view[sel].r+' · PT '+view[sel].pt.toFixed(0)+'.00 · upside '+(view[sel].up>=0?'+':'')+view[sel].up.toFixed(1)+'% · next '+view[sel].cat;
  else pick.textContent='▸ no name selected';
}
body.addEventListener('keydown',function(e){
  if(e.key==='ArrowDown'||e.key==='ArrowUp'){
    e.preventDefault();sel=Math.max(0,Math.min(view.length-1,sel+(e.key==='ArrowDown'?1:-1)));paint();
    if(body.children[sel])body.children[sel].scrollIntoView({block:'nearest'});
  }else if(e.key==='Enter'){e.preventDefault();paint();}
  else if(e.key==='F6'){e.preventDefault();onlyStale=!onlyStale;sel=0;render();}
  else if(e.key==='F9'){e.preventDefault();si=(si+1)%sorts.length;render();}
});
kStale.addEventListener('click',function(){onlyStale=!onlyStale;sel=0;render();});
kSort.addEventListener('click',function(){si=(si+1)%sorts.length;render();});
render();
